import { LIGHT_YEARS_PER_PARSEC, type DistanceUnit } from './astronomy'
import { formatNumber } from './format'
import { AU_METERS, SOLAR_RADIUS_METERS } from './luminosity-properties'
import planetarySystems from './data/planetary-systems.json'
import data from './data/top-lists.json'

/** Catalog record that represents a listed star; generated by scripts/author-top-lists.py. */
export interface TopListObject { catalog: string; id: string; designation: string | null }
/** Ranked lists carry a metric value; descriptive lists carry text fields labelled by the list's columns. */
interface TopListEntry { name: string; value?: number; fields?: string[]; distance_pc: number; distance_source?: string; note?: string; constellation: string; object: TopListObject | null }
interface TopList { id: string; title: string; metric?: string; unit?: string; columns?: string[]; markers?: string; source: { label: string; url: string }; entries: TopListEntry[] }

interface TopListOptions {
  distanceUnit: DistanceUnit
  onSelect(object: TopListObject): void
}

const lists = data.lists as TopList[]
const solarRadiiPerAu = AU_METERS / SOLAR_RADIUS_METERS
const solarOrbits = planetarySystems.systems.find(({ hostStarId }) => hostStarId === 'sun')!.planets
  .map((planet) => ({ name: planet.name, radius: planet.semiMajorAxisAu * solarRadiiPerAu }))

/** Orbits inside the listed range, plus the nearest orbit beyond each end. */
function orbitMarkers(entries: readonly TopListEntry[]) {
  const max = entries[0]!.value!, min = entries.at(-1)!.value!
  const above = solarOrbits.find((orbit) => orbit.radius > max)
  const below = solarOrbits.findLast((orbit) => orbit.radius < min)
  return solarOrbits.filter((orbit) => orbit === above || orbit === below || (orbit.radius >= min && orbit.radius <= max))
}

function cell(content: string | Node, className?: string): HTMLTableCellElement {
  const td = document.createElement('td')
  if (className) td.className = className
  td.append(content)
  return td
}

export function initializeTopLists(signal: AbortSignal, options: () => TopListOptions) {
  const terms = document.getElementById('top-lists-terms')!
  const heading = document.getElementById('top-lists-title')!
  const cols = document.getElementById('top-lists-cols')!
  const head = document.getElementById('top-lists-head')!
  const body = document.getElementById('top-lists-rows')!
  const source = document.getElementById('top-lists-source') as HTMLAnchorElement
  const notes = document.getElementById('top-lists-notes')!
  const scroll = document.getElementById('top-lists-detail')!.querySelector<HTMLElement>('.card-scroll-content')!
  let selected = lists[0]!

  terms.replaceChildren(...lists.map((list) => {
    const button = document.createElement('button')
    button.type = 'button'
    button.className = 'glossary-term'
    button.textContent = list.title
    button.dataset.list = list.id
    button.setAttribute('aria-controls', 'top-lists-detail')
    return button
  }))

  const render = () => {
    const { distanceUnit } = options()
    const distanceScale = distanceUnit === 'ly' ? LIGHT_YEARS_PER_PARSEC : 1
    for (const button of terms.querySelectorAll<HTMLButtonElement>('button')) {
      button.setAttribute('aria-current', String(button.dataset.list === selected.id))
    }
    heading.textContent = selected.title
    const { columns } = selected
    cols.parentElement!.classList.toggle('top-list-fields', !!columns)
    const valueCols = columns ? columns.map((_, i) => `top-list-field-${i}`) : ['top-list-number']
    cols.replaceChildren(...['top-list-rank', '', 'top-list-number', ...valueCols, 'top-list-constellation'].map((className) => {
      const col = document.createElement('col')
      if (className) col.className = className
      return col
    }))
    head.replaceChildren(...['#', 'Name', `Distance (${distanceUnit})`, ...(columns ?? [`${selected.metric} (${selected.unit})`]), 'Constellation'].map((label) => {
      const th = document.createElement('th')
      th.scope = 'col'
      th.textContent = label
      return th
    }))
    const markers = selected.markers === 'solar-orbits' ? orbitMarkers(selected.entries) : []
    const marker = (orbit: typeof markers[number]) => {
      const row = document.createElement('tr')
      row.className = 'top-list-marker'
      const td = cell(`Orbit of ${orbit.name} · ${formatNumber(orbit.radius, 0)} ${selected.unit}`)
      td.colSpan = head.childElementCount
      row.append(td)
      return row
    }
    const rows: HTMLTableRowElement[] = []
    selected.entries.forEach((entry, index) => {
      // Markers descend with the ranked values, so each lands above the first smaller star.
      while (markers.length && markers.at(-1)!.radius > entry.value!) rows.push(marker(markers.pop()!))
      const row = document.createElement('tr')
      let name: string | Node = entry.name
      if (entry.object) {
        row.dataset.entry = String(index)
        const button = document.createElement('button')
        button.type = 'button'
        button.className = 'top-list-select'
        button.textContent = entry.name
        button.setAttribute('aria-label', `Select ${entry.name}`)
        name = button
      } else {
        row.className = 'is-missing'
        row.title = 'Not in Star View’s catalogs'
      }
      // Literature distances carry about three significant figures.
      const distance = cell((entry.distance_pc * distanceScale).toLocaleString('en-US', { maximumSignificantDigits: 3 }))
      if (entry.distance_source) distance.title = entry.distance_source
      // Fields can exceed their column, so each carries its full text as a tooltip.
      const values = entry.fields?.map((field) => {
        const td = cell(field || '—')
        if (field) td.title = field
        return td
      }) ?? [cell(formatNumber(entry.value!, 0))]
      // Notes add context to the last value, such as a differing reviewed value or an expected supernova time.
      if (entry.note) values.at(-1)!.append(' *')
      row.append(cell(String(index + 1)), cell(name), distance, ...values, cell(entry.constellation))
      rows.push(row)
    })
    rows.push(...markers.reverse().map(marker))
    body.replaceChildren(...rows)
    const noted = selected.entries.filter((entry) => entry.note)
    notes.hidden = !noted.length
    notes.textContent = noted.map((entry) => `* ${entry.name}: ${entry.note}`).join('\n')
    source.href = selected.source.url
    source.textContent = selected.source.label
  }

  terms.addEventListener('click', (event) => {
    const id = event.target instanceof Element ? event.target.closest<HTMLButtonElement>('button')?.dataset.list : undefined
    const list = lists.find((candidate) => candidate.id === id)
    if (!list || list === selected) return
    selected = list
    render()
    scroll.scrollTop = 0
  }, { signal })
  body.addEventListener('click', (event) => {
    const index = event.target instanceof Element ? event.target.closest<HTMLElement>('tr[data-entry]')?.dataset.entry : undefined
    const object = index === undefined ? null : selected.entries[Number(index)]!.object
    if (object) options().onSelect(object)
  }, { signal })
  return { open: render }
}
